      const rank = perBeat.get(b) ?? 0;
      perBeat.set(b, rank + 1);
      const beat = beats[b];
      const count = beats.some((bt) => bt.reveal != null) ? beatOf.filter((x) => x === b).length : S <= B ? 1 : Math.ceil(S / B) || 1;
